"use client";

import {
  CloudletProvider,
  Toaster as CloudletToaster,
  type ReactCloudletController,
  type ToasterProps as CloudletToasterProps,
} from "@cloudlet/toast";
import type { ReactNode } from "react";
import "@cloudlet/toast/styles.css";
import "./toaster.css";

export interface ToasterProps extends CloudletToasterProps {
  /**
   * The application owns this instance and disposes it when its owner unmounts.
   * `null` until the owner creates it: children render, the Toaster waits.
   */
  controller: ReactCloudletController | null;
  children?: ReactNode;
}

/** A local theme adapter. All notification behavior stays in @cloudlet/toast. */
export function Toaster({ controller, children, ...options }: ToasterProps) {
  return (
    <CloudletProvider controller={controller}>
      {children}
      <CloudletToaster {...options} />
    </CloudletProvider>
  );
}

/* Load after @cloudlet/toast/styles.css. Modern shadcn tokens are full colors. */
/* Both body portals and custom containers inherit tokens from their ancestors. */
@media (forced-colors: none) {
  .cloudlet-host[data-theme] {
    --cloudlet-background: var(--popover, var(--background, #fff));
    --cloudlet-foreground: var(--popover-foreground, var(--foreground, #171717));
    --cloudlet-muted: var(--muted-foreground, #61616a);
    --cloudlet-border: var(--border, #dedee3);
    --cloudlet-focus: var(--ring, #245cdb);
    --cloudlet-action-background: var(--accent, #ededf0);
    --cloudlet-font-family: var(--font-sans, system-ui, sans-serif);
  }
}
